{
  "query": "site:ccmc.gsfc.nasa.gov 3I/ATLAS OR \"C/2025 N1\" OR Deca",
  "mode": "standard"
}

{
  "query": "\"3I/ATLAS\" AGU 2025 fall meeting abstract plasma solar wind interaction",
  "mode": "extended"
}

{
  "query": "\"3I/ATLAS\" X-ray emission paper ApJ Letters 2026 XMM-Newton EPIC charge exchange luminosity",
  "mode": "extended"
}

{
  "url": "https://phys.org/news/2025-12-xmm-newton-comet-3iatlas-ray.html",
  "prompt": "Extract observation date/time and duration, distances (from Earth, from Sun), instrument, quantitative results, scientist quotes about solar wind, and any mention of solar wind conditions."
}

{
  "query": "XRISM Xtend 3I/ATLAS paper 2026 PASJ OR ApJ solar wind charge exchange coma",
  "mode": "extended"
}

{
  "url": "https://www.xrism.jaxa.jp/en/topics/news/1208/",
  "prompt": "Extract all details: observation dates, comet heliocentric and geocentric distances, extent of emission, spectral lines, any mention of solar wind conditions, team names, follow-up papers."
}

{
  "query": "November 2025 geomagnetic storm X5.1 flare CME arXiv paper solar wind ACE Wind DSCOVR",
  "mode": "extended"
}

{
  "command": "cd /tmp/claude-1000/-mnt-c-Users-cabot-OneDrive-Documents-Research-Cambridge-X3I/c4794a53-4881-4aa9-8b9b-7c033457fa8b/scratchpad && python3 -I q.py 'all:\"November 2025\" AND (all:storm OR all:CME OR all:\"solar wind\" OR all:flare)' 'all:\"2025 November\" AND (all:storm OR all:CME OR all:\"solar wind\" OR all:flare)' 'all:\"December 2025\" AND (all:CME OR all:\"solar wind\" OR all:\"high-speed stream\")' 2>&1 | head -150",
  "description": "Query arXiv for November/December 2025 space weather papers"
}

{
  "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12986641/",
  "prompt": "Give authors, journal, volume/date, DOI. Extract all quoted in-situ solar wind values at L1 (ACE/Wind/DSCOVR): shock arrival time(s), solar wind speed (pre- and post-shock, peak), proton density, IMF |B| and Bz (min), dynamic pressure, temperature, sheath/magnetic cloud timing, CME launch time and speed (LASCO/STEREO), and the flare details. Also any mention of STEREO-A in situ data or other CMEs/HSS in November 2025. Quote numbers with units and UT times."
}

{
  "url": "https://arxiv.org/abs/2603.14454",
  "prompt": "Give authors, title, date, journal ref, abstract. List any solar wind values quoted (speed, density, Bz, dynamic pressure) with times."
}

{
  "query": "space weather late November early December 2025 CME geomagnetic storm December 1 2025 high-speed stream coronal hole",
  "mode": "extended"
}

{
  "url": "https://earthsky.org/sun/sun-activity-archive-for-november-2025/",
  "prompt": "List daily solar wind values (speed km/s, density, Bt/Bz), CMEs, high-speed streams, and geomagnetic storm levels reported for November 20-30, 2025. Quote numbers with dates."
}

{
  "url": "https://earthsky.org/sun/sun-activity-archive-for-december-2025/",
  "prompt": "List daily solar wind values (speed km/s, density if given, Bt/Bz), CMEs, high-speed streams, and geomagnetic storm levels reported for December 1-10, 2025. Quote numbers with dates and UTC times."
}

{
  "url": "https://earthsky.org/sun/sun-activity-archive-for-december-2025/",
  "offset": 150000,
  "prompt": "List daily solar wind values (speed km/s, density if given, Bt/Bz), CMEs, high-speed streams, and geomagnetic storm levels reported for December 1-10, 2025. Quote numbers with dates and UTC times."
}

{
  "query": "X1.9 flare 1 December 2025 CME AR4299 OR AR14299 OR AR4294 analysis",
  "mode": "extended"
}

{
  "query": "NOAA SWPC space weather highlights November 24-30 2025 OR \"1 December 2025\" weekly report solar wind",
  "mode": "standard"
}
